from pathlib import Path
from dataclasses import dataclass, field
import base64,subprocess
@dataclass
class N:
    off:int; tag:int; val:bytes; hdr:bytes; end:int; ch:list=field(default_factory=list)
    def __str__(self):return f'{self.off}:{self.tag:02x}[{len(self.val)}]'
def parse(b,p=0):
    o=p;t=b[p];p+=1
    if t&31==31:
        while b[p]&128:p+=1
        p+=1
    l=b[p];p+=1
    indef=l==128
    if l>128:
        k=l&127;l=int.from_bytes(b[p:p+k],'big');p+=k
    q=p;c=[]
    if indef:
        while b[q:q+2]!=b'\0\0':
            n,q=parse(b,q);c.append(n)
        v=b[p:q];q+=2
    else:
        q=p+l;v=b[p:q]
        if t&32:
            z=p
            while z<q:
                n,z=parse(b,z);c.append(n)
    return N(o,t,v,b[o:p],q,c),q

def walk(n,path=''):
    yield path,n
    for i,c in enumerate(n.ch):yield from walk(c,path+'/'+str(i))
def length(k):
    return bytes([k]) if k<128 else bytes([128+(k.bit_length()+7)//8])+k.to_bytes((k.bit_length()+7)//8,'big')

def report(n,b, embedded=False):
    for path,x in walk(n):
        items=[]
        if x.hdr[1:]==b'\x80':items.append('indef')
        elif x.hdr[1:]!=length(len(x.val)):items.append('length='+x.hdr.hex())
        if x.tag in (0x23,0x24):items.append('constructed string')
        if x.tag==2 and len(x.val)>1 and (x.val[0]==0 and x.val[1]<128 or x.val[0]==255 and x.val[1]>=128):items.append('padded integer '+x.val.hex())
        if x.tag==1 and x.val==b'\x00':items.append('FALSE')
        if x.tag==0x31 and any(b[a.off:a.end]>=b[c.off:c.end] for a,c in zip(x.ch,x.ch[1:])):items.append('raw SET unsorted')
        if x.tag==0xa0 and x.ch and x.ch[0].tag==2 and x.ch[0].val==b'\x00':items.append('version DEFAULT')
        if items:print(' ',path,str(x),', '.join(items))
        if x.tag==4 and not embedded:
            try:
                inner,end=parse(b,x.off+len(x.hdr))
                if end==x.end:report(inner,b,True)
            except Exception:pass
if __name__=='__main__':
    for f in sorted(Path('/app/corpus').glob('*.der')):
        b=f.read_bytes();n,end=parse(b)
        print(f.name,subprocess.run(['/app/appliance/accepts',str(f)],capture_output=True,text=True).stdout.strip())
        report(n,b)
