    if n < 128:
        return bytes((n,))
    b = n.to_bytes((n.bit_length() + 7) // 8, 'big')
    return bytes((128 | len(b),)) + b


def base128(n):
    parts = [n & 127]
    n >>= 7
    while n:
        parts.append(128 | (n & 127))
        n >>= 7
    return bytes(reversed(parts))


